 [MenuItem("CityForge/Ground Study/MapMagic Meadow Zoom 1")]
 public static void Run(){
  var target=UnityEditor.Build.NamedBuildTarget.Standalone;var defines=PlayerSettings.GetScriptingDefineSymbols(target);if(defines.Contains("MM_NATIVE")){PlayerSettings.SetScriptingDefineSymbols(target,defines.Replace(";MM_NATIVE","").Replace("MM_NATIVE;","").Replace("MM_NATIVE",""));File.WriteAllText(Trigger,"retry");return;}
