  scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);
  var graph=ScriptableObject.CreateInstance<Graph>();var noise=(Noise200)Generator.Create(typeof(Noise200));noise.seed=730421;noise.size=180;noise.intensity=.28f;noise.detail=.3f;graph.Add(noise);
  var height=(HeightOutput200)Generator.Create(typeof(HeightOutput200));height.guiPosition=new Vector2(230,0);graph.Add(height);graph.Link(height,noise);
  string gp=Root+"MeadowGraph.asset"; if(AssetDatabase.LoadAssetAtPath<Graph>(gp))AssetDatabase.DeleteAsset(gp);AssetDatabase.CreateAsset(graph,gp);
  mm=new GameObject("MapMagic meadow authoring source").AddComponent<MapMagicObject>();mm.graph=graph;mm.tileSize=new Vector2D(256,256);mm.tileResolution=MapMagicObject.Resolution._257;mm.globals.height=40;mm.globals.heightMainApply=HeightOutput200.ApplyType.SetHeights;mm.draftsInEditor=false;mm.draftsInPlaymode=false;mm.tiles.allowMove=false;mm.hideFarTerrains=false;
