 static float Path(float z)=>112+18*Mathf.Sin(z*.026f)+.12f*(z-128);
 static float Woodland(float x,float z)=>Mathf.Clamp01((Vector2.Distance(new Vector2(x,z),new Vector2(125,110))-43)/25);
 static void Applied(TerrainTile tile,MapMagic.Products.TileData data,StopToken stop){if(mm==null||data.isDraft||tile.GetTerrain(false)==null)return;var t=tile.GetTerrain(false);if(t.transform.parent!=mm.transform&&!t.transform.IsChildOf(mm.transform))return; var source=mm;mm=null;EditorApplication.delayCall+=()=>{if(source)UnityEngine.Object.DestroyImmediate(source);Build(t);};}
 static void Build(Terrain t){
  var terrainMat=new Material(Shader.Find("Universal Render Pipeline/Terrain/Lit"));SaveAsset(terrainMat,Root+"Terrain.mat");t.materialTemplate=terrainMat;var td=t.terrainData;int n=td.heightmapResolution;var h=td.GetHeights(0,0,n,n);for(int z=0;z<n;z++)for(int x=0;x<n;x++){float wx=x*256f/(n-1),wz=z*256f/(n-1);float rise=6*Mathf.Exp(-((wx-158)*(wx-158)+(wz-155)*(wz-155))/2600);float clear=1-Woodland(wx,wz);h[z,x]=(h[z,x]*40*.35f+rise+2)* (1-.12f*clear)/40;}td.SetHeights(0,0,h);
  string[] keys={"Forest1","Forest3","Forest4","Mud"};var layers=new TerrainLayer[4];for(int i=0;i<4;i++){var l=new TerrainLayer();string diffuse=Root+keys[i]+"_Diffuse.png";if(!File.Exists(diffuse))File.Copy(GroundZoom1Study.Art+keys[i]+"_Albedo.png",diffuse);AssetDatabase.ImportAsset(diffuse);var importer=(TextureImporter)AssetImporter.GetAtPath(diffuse);importer.alphaSource=TextureImporterAlphaSource.None;importer.maxTextureSize=2048;importer.anisoLevel=8;importer.SaveAndReimport();l.diffuseTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(diffuse);l.normalMapTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(GroundZoom1Study.Art+keys[i]+"_Normal.png");l.tileSize=Vector2.one*(i==3?6:9+i*3);l.tileOffset=new Vector2(i*13,i*7);l.normalScale=.12f;l.diffuseRemapMax=new Vector4(.6f,.65f,.5f,1);l.smoothness=.1f;string p=Root+keys[i]+".terrainlayer";if(AssetDatabase.LoadAssetAtPath<TerrainLayer>(p))AssetDatabase.DeleteAsset(p);AssetDatabase.CreateAsset(l,p);layers[i]=l;}td.terrainLayers=layers;
  td.alphamapResolution=512;var a=new float[512,512,4];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float wx=x*256f/511,wz=z*256f/511;float path=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.4f,3.3f,Mathf.Abs(wx-Path(wz))));float macro=Mathf.PerlinNoise(wx*.019f+42,wz*.019f+17);float wood=Woodland(wx,wz);a[z,x,0]=(1-path)*(1-wood)*(.45f+.4f*macro);a[z,x,1]=(1-path)*(1-wood)*( .55f-.4f*macro);a[z,x,2]=(1-path)*wood;a[z,x,3]=path;}td.SetAlphamaps(0,0,a);t.basemapDistance=1000;t.shadowCastingMode=ShadowCastingMode.On;
  string tp=Root+"MeadowTerrain.asset";if(AssetDatabase.LoadAssetAtPath<TerrainData>(tp))AssetDatabase.DeleteAsset(tp);AssetDatabase.CreateAsset(td,tp);
  UnityEngine.Random.InitState(901);
  var root=new GameObject("Authored woodland edge");string[] trees={"SummerForest/SummerMaple","SummerForest/SummerLinden","SummerForest/SummerElm","FraserFirA","HimalayanBirchA"};
  for(int i=0;i<1800;i++){float x=UnityEngine.Random.Range(20f,236f),z=UnityEngine.Random.Range(20f,236f);float wood=Woodland(x,z);float cluster=Mathf.PerlinNoise(x*.037f,z*.037f);if(UnityEngine.Random.value>wood*cluster*.65f||Mathf.Abs(x-Path(z))<7)continue;var prefab=Resources.Load<GameObject>("Trees/"+trees[i%trees.Length]);if(!prefab)continue;var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);foreach(var lod in go.GetComponentsInChildren<LODGroup>())lod.ForceLOD(0);go.transform.SetParent(root.transform);go.transform.position=new Vector3(x,t.SampleHeight(new Vector3(x,0,z)),z);go.transform.rotation=Quaternion.Euler(0,UnityEngine.Random.Range(0,360),0);go.transform.localScale*=UnityEngine.Random.Range(.65f,1.05f);}
  // Small foliage repeats the woodland clusters, leaving the building meadow and path readable.
  var shrubPrefab=Resources.Load<GameObject>("Trees/DenseForestTrees/A_Rounded_Summer");for(int i=0;i<350;i++){float x=UnityEngine.Random.Range(20f,236f),z=UnityEngine.Random.Range(20f,236f);if(Woodland(x,z)<.2f||Mathf.Abs(x-Path(z))<5||Mathf.PerlinNoise(x*.06f,z*.06f)<.5f)continue;var go=(GameObject)PrefabUtility.InstantiatePrefab(shrubPrefab,scene);foreach(var lod in go.GetComponentsInChildren<LODGroup>())lod.ForceLOD(0);go.transform.SetParent(root.transform);go.transform.position=new Vector3(x,t.SampleHeight(new Vector3(x,0,z)),z);go.transform.localScale*=UnityEngine.Random.Range(.08f,.18f);go.transform.rotation=Quaternion.Euler(0,UnityEngine.Random.Range(0,360),0);}
  var vertices=new System.Collections.Generic.List<Vector3>();var colors=new System.Collections.Generic.List<Color>();var uv=new System.Collections.Generic.List<Vector2>();var triangles=new System.Collections.Generic.List<int>();
  for(int i=0;i<65000;i++){float x=UnityEngine.Random.Range(12f,244f),z=UnityEngine.Random.Range(12f,244f);if(Mathf.Abs(x-Path(z))<3.5f||Mathf.PerlinNoise(x*.08f,z*.08f)<.38f)continue;float y=t.SampleHeight(new Vector3(x,0,z));float blade=UnityEngine.Random.Range(.22f,.65f);float angle=UnityEngine.Random.value*6.28f;var side=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*.16f;var b=new Vector3(x,y,z);int start=vertices.Count;vertices.Add(b-side);vertices.Add(b+side);vertices.Add(b+Vector3.up*blade+side*.4f);triangles.Add(start);triangles.Add(start+1);triangles.Add(start+2);Color c=Color.Lerp(new Color(.30f,.38f,.12f),new Color(.40f,.47f,.18f),UnityEngine.Random.value);for(int j=0;j<3;j++){colors.Add(c);uv.Add(j==2?Vector2.up:Vector2.zero);}}
  var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.SetColors(colors);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();SaveAsset(mesh,Root+"MeadowTufts.asset");var grass=new GameObject("Clustered meadow tufts");grass.AddComponent<MeshFilter>().sharedMesh=mesh;var grassMat=new Material(Shader.Find("CityForge/Study Meadow Grass"));SaveAsset(grassMat,Root+"MeadowTufts.mat");grass.AddComponent<MeshRenderer>().sharedMaterial=grassMat;
  var pv=new System.Collections.Generic.List<Vector3>();var pu=new System.Collections.Generic.List<Vector2>();var pi=new System.Collections.Generic.List<int>();for(int j=0;j<=256;j++){float z=j;float x=Path(z);for(int k=0;k<2;k++){float px=x+(k==0?-2.3f:2.3f)*( .9f+.2f*Mathf.PerlinNoise(z*.18f,37));pv.Add(new Vector3(px,t.SampleHeight(new Vector3(px,0,z))+.045f,z));pu.Add(new Vector2(k,z/6));}if(j>0){int q=j*2;pi.AddRange(new[]{q-2,q,q-1,q-1,q,q+1});}}var pm=new Mesh();pm.SetVertices(pv);pm.SetUVs(0,pu);pm.SetTriangles(pi,0);pm.RecalculateNormals();SaveAsset(pm,Root+"DirtPath.asset");var pathObject=new GameObject("Authored dirt path");pathObject.AddComponent<MeshFilter>().sharedMesh=pm;var pathMat=new Material(Shader.Find("CityForge/Study Dirt Path"));pathMat.SetTexture("_BaseMap",layers[3].diffuseTexture);pathMat.SetColor("_BaseColor",new Color(.95f,.88f,.72f));pathMat.SetFloat("_Smoothness",0);pathMat.SetFloat("_Cull",0);SaveAsset(pathMat,Root+"DirtPath.mat");pathObject.AddComponent<MeshRenderer>().sharedMaterial=pathMat;
  var sun=new GameObject("Summer sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.8f;sun.color=new Color(1,.96f,.86f);sun.shadows=LightShadows.Soft;sun.shadowStrength=.7f;sun.transform.rotation=Quaternion.Euler(48,225,0);
  var sh=new SphericalHarmonicsL2();sh.AddAmbientLight(new Color(.46f,.48f,.46f));RenderSettings.ambientProbe=sh;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.45f,.53f,.60f);RenderSettings.ambientEquatorColor=new Color(.3f,.33f,.29f);RenderSettings.ambientGroundColor=new Color(.16f,.15f,.12f);RenderSettings.fog=false;
  camera=new GameObject("Gameplay Zoom 1 camera").AddComponent<Camera>();camera.orthographic=true;camera.backgroundColor=new Color(.85f,.87f,.83f);camera.clearFlags=CameraClearFlags.SolidColor;camera.GetUniversalAdditionalCameraData().renderPostProcessing=true;var rig=camera.gameObject.AddComponent<CityForgeCameraController>();rig.FrameArea(2048,120,new Vector3(128,0,128));typeof(CityForgeCameraController).GetField("focus",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(rig,new Vector3(128,7,128));rig.SetZoomLevel(1);rig.ApplyPose();camera.farClipPlane=5000;
  var v=new GameObject("Summer presentation").AddComponent<Volume>();v.isGlobal=true;var profile=ScriptableObject.CreateInstance<VolumeProfile>();profile.Add<Tonemapping>(true).mode.Override(TonemappingMode.ACES);profile.Add<ColorAdjustments>(true).postExposure.Override(.2f);SaveAsset(profile,Root+"SummerLighting.asset");v.sharedProfile=profile;
  AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"MeadowZoom1.unity");captureAt=EditorApplication.timeSinceStartup+8;Debug.Log("MEADOW authored, ortho="+camera.orthographicSize);
 }
 static void SaveAsset(UnityEngine.Object asset,string path){if(AssetDatabase.LoadMainAssetAtPath(path))AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(asset,path);}
 static void Capture(){var rt=new RenderTexture(3840,2160,24);rt.Create();var old=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var image=new Texture2D(3840,2160,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,3840,2160),0,0);image.Apply();Directory.CreateDirectory(System.IO.Path.GetDirectoryName(Output));File.WriteAllBytes(Output,image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);Debug.Log("MEADOW CAPTURE COMPLETE");}finally{RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}
